{"command":"python3 - <<'EOF'
import csv
rows=list(csv.DictReader(open('outputs/t02_eurostat_raw.csv',newline='')))
inds=[]
for r in rows:
    if r['indicator_id'] not in inds: inds.append(r['indicator_id'])
data={}
for r in rows:
    data.setdefault((r['city_id'],r['year']),{})[r['indicator_id']]=r['value']
# row order: preserve first appearance order of (city_id,year)
order=[]
seen=set()
for r in rows:
    k=(r['city_id'],r['year'])
    if k not in seen:
        seen.add(k); order.append(k)
names={}
for r in rows: names[(r['city_id'])]=r['city_name']
with open('outputs/t11_city_indicator_matrix.csv','w',newline='') as f:
    w=csv.writer(f, quoting=csv.QUOTE_MINIMAL, lineterminator='\r\n')
    w.writerow(['city_id','city_name','year']+inds)
    for cid,yr in order:
        d=data[(cid,yr)]
        w.writerow([cid,names[cid],yr]+[d.get(i,'') for i in inds])
print('rows:',len(order))
EOF
head -3 outputs/t11_city_indicator_matrix.csv | cut -c1-200"}
